structured_output.command:
IMG=/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat
perl -e '
my ($img)=@ARGV;
open my $fh, "<:raw", $img or die "open: $!";
local $/; my $d = <$fh>; close $fh;
my @t;
for my $i (0..255) { my $c=$i; for (1..8) { $c = ($c & 1) ? (0xEDB88320 ^ ($c >> 1)) : ($c >> 1); } $t[$i]=$c; }
sub crc32 { my $s=shift; my $c=0xFFFFFFFF; for my $b (unpack("C*",$s)) { $c = $t[($c ^ $b) & 0xFF] ^ ($c >> 8); } return $c ^ 0xFFFFFFFF; }
my $cand = "PASSWORD=8XDP5Q2RT9ZK7VB3BV4WW54\n";
printf("cand len=%d crc=0x%08X\n", length($cand), crc32($cand));
printf("cand-1 len=%d crc=0x%08X\n", length($cand)-1, crc32(substr($cand,0,length($cand)-1)));
printf("frag  crc=0x%08X\n", crc32("PASSWORD=8XDP5Q2RT9Z"));
for my $sig ("\x50\x4b\x03\x04", "\x50\x4b\x01\x02", "\x50\x4b\x05\x06") {
  my @off; my $p=0;
  while (($p = index($d,$sig,$p)) >= 0) { push @off,$p; $p++; }
  my $hex = join(",", map { sprintf("0x%X",$_) } @off[0..($#off<9?$#off:9)]);
  printf("sig %s count=%d offsets=%s\n", unpack("H*",$sig), scalar(@off), $hex);
}
my $s1 = substr($d,1048560,160);
printf("around1048560: %s\n", unpack("H*",$s1));
my $s2 = substr($d,3145640,200);
printf("around3145640: %s\n", unpack("H*",$s2));
' "$IMG"
echo '--- hexdump around 1048640 ---'
od -A d -t x1z -j 1048636 -N 96 "$IMG"
echo '--- hexdump around 3145700 ---'
od -A d -t x1z -j 3145696 -N 96 "$IMG"

