structured_output.command:
cd /app && printf '%s\n' '8XDP5Q2RT9ZK7VB3BV4WW54' > /app/recovered_passwords.txt
PW=$(head -n1 /app/recovered_passwords.txt)
echo "password=[$PW] len=${#PW}"
case "$PW" in 8XD*W54) echo 'prefix/suffix OK';; *) echo 'prefix/suffix FAIL';; esac
printf '%s' "$PW" | grep -qE '^[A-Z0-9]{23}$' && echo 'charset/length OK' || echo 'charset/length FAIL'
perl -e '
my ($pw,$img)=@ARGV;
open my $fh,"<:raw",$img or die "open: $!"; local $/; my $d=<$fh>; close $fh;
my $a=substr($d,1048652,20);
my $b=substr($d,3145728,13);
printf("frag1=[%s] frag2=[%s]\n",$a,$b);
my @t; for my $i (0..255){my $c=$i; for(1..8){$c=($c&1)?(0xEDB88320^($c>>1)):($c>>1)} $t[$i]=$c}
sub crc32{my $c=0xFFFFFFFF; for my $x (unpack("C*",shift)){$c=$t[($c^$x)&0xFF]^($c>>8)} return $c^0xFFFFFFFF}
my $rec=$a.$b;
printf("reconstructed len=%d pattern_ok=%d crc=0x%08X expected=0xB0725DC4 %s\n",length($rec),($rec=~/^PASSWORD=[A-Z0-9]{23}\n$/)?1:0,crc32($rec),crc32($rec)==0xB0725DC4?"CRC_MATCH":"CRC_FAIL");
print(($rec eq "PASSWORD=$pw\n")?"RECONSTRUCTION CONSISTENT WITH PASSWORD\n":"INCONSISTENT\n");
' "$PW" /app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat
echo '--- final file ---'; cat -A /app/recovered_passwords.txt; ls -l /app/recovered_passwords.txt

